import {IconButton} from '@primer/react'
import {TrashIcon} from '@primer/octicons-react'
import {useId} from 'react'

import styles from './PickerSection.module.css'

/* ────────────────────────────────────────────────────────────────────────── */
/* PickerSection — wraps a section header + card list or empty state          */
/* ────────────────────────────────────────────────────────────────────────── */

export interface PickerSectionProps {
  /** Section heading text. */
  label: string
  /** Smaller description below the label. */
  caption?: React.ReactNode
  /** Show a required indicator next to the label. */
  required?: boolean
  /** The ActionMenu element used to add new items. */
  menu: React.ReactNode
  /** Whether there are items currently selected (controls empty state). */
  hasItems: boolean
  /** Optional custom empty-state copy shown in place of the default. */
  emptyStateText?: React.ReactNode
  /** Optional footer row shown under the empty-state message. */
  emptyStateFooter?: React.ReactNode
  /** Optional footer rendered inside the bordered container, below the card list. */
  footer?: React.ReactNode
  /** Card list content rendered when hasItems is true. */
  children: React.ReactNode
}

export function PickerSection({
  label,
  caption,
  required,
  menu,
  hasItems,
  emptyStateText,
  emptyStateFooter,
  footer,
  children,
}: PickerSectionProps) {
  const labelId = useId()

  return (
    <div className={styles.section} role="group" aria-labelledby={labelId}>
      <div className={styles.sectionHeader}>
        <div className={styles.sectionHeaderContent}>
          <span id={labelId} className={styles.label}>
            <span>{label}</span>
            {required && (
              <>
                <span aria-hidden="true"> *</span>
                <span className="sr-only"> (required)</span>
              </>
            )}
          </span>
          {caption != null && <span className={styles.caption}>{caption}</span>}
        </div>
        <div className={styles.sectionHeaderMenu}>{menu}</div>
      </div>
      {hasItems ? (
        <div className={styles.cardListWrapper}>
          {/* eslint-disable-next-line jsx-a11y/no-redundant-roles -- list-style:none strips semantics in Safari/VoiceOver */}
          <ul className={styles.cardList} role="list">
            {children}
          </ul>
          {footer != null && <div className={styles.cardListFooter}>{footer}</div>}
        </div>
      ) : (
        <div className={styles.emptyStateContainer}>
          <div className={styles.emptyState}>{emptyStateText ?? <>No {label.toLowerCase()} yet</>}</div>
          {emptyStateFooter != null && <div className={styles.emptyStateFooter}>{emptyStateFooter}</div>}
          {footer != null && <div className={styles.cardListFooter}>{footer}</div>}
        </div>
      )}
    </div>
  )
}

/* ────────────────────────────────────────────────────────────────────────── */
/* PickerCard — a single card row with icon, title, remove, and body          */
/* ────────────────────────────────────────────────────────────────────────── */

export interface PickerCardProps {
  /** Icon element (rendered at 16px). */
  icon?: React.ReactNode
  /** Optional inline style for the icon wrapper (e.g. color override). */
  iconStyle?: React.CSSProperties
  /** Card title text. */
  title: string
  /** Accessible label for the remove button. */
  removeLabel: string
  /** Called when the remove button is clicked. */
  onRemove: () => void
  /** Optional body content below the header (descriptions, fields, etc). */
  children?: React.ReactNode
}

export function PickerCard({icon, iconStyle, title, removeLabel, onRemove, children}: PickerCardProps) {
  return (
    <li className={styles.cardRow}>
      <div className={styles.cardContent}>
        <div className={styles.cardHeader}>
          {icon != null && (
            <span className={styles.cardIcon} style={iconStyle} aria-hidden="true">
              {icon}
            </span>
          )}
          <span className={styles.cardTitle}>{title}</span>
        </div>
        {children}
      </div>
      <div className={styles.cardActions}>
        <IconButton icon={TrashIcon} variant="invisible" size="small" onClick={onRemove} aria-label={removeLabel} />
      </div>
    </li>
  )
}
