import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {KebabHorizontalIcon, PauseIcon, PencilIcon, PlayIcon, TrashIcon, WorkflowIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton, Label, Spinner} from '@primer/react'
import {useNavigate} from '@github-ui/use-navigate'
import {useCurrentRepository} from '@github-ui/current-repository'
import {sendEvent} from '@github-ui/hydro-analytics'
import {ListItemTitle} from '@github-ui/agent-sessions/components/task-list/ListParts'
import {useCallback, useState} from 'react'
import type {Automation} from '../../types/automations-payload'
import {DeleteAutomationDialog} from './DeleteAutomationDialog'
import {ToggleAutomationDialog} from './ToggleAutomationDialog'
import {ConvertToWorkflowDialog} from './ConvertToWorkflowDialog'
import {RunAutomationDialog} from './RunAutomationDialog'
import {useRunAutomationAction} from '../../hooks/use-run-automation-action'
import {useTriggers} from '@github-ui/automation-form/use-triggers'
import {getAutomationPath} from './automation-paths'
import styles from './AutomationListItem.module.css'

interface AutomationListItemProps {
  automation: Automation
  onActiveLimitReached: () => void
  onAutomationDisabled?: () => void
  onRunError?: (message: string) => void
  onRunStart?: () => void
}

export function AutomationListItem({
  automation,
  onActiveLimitReached,
  onAutomationDisabled,
  onRunError,
  onRunStart,
}: AutomationListItemProps) {
  const navigate = useNavigate()
  const repo = useCurrentRepository()
  const href = getAutomationPath(repo, automation.id)
  const {triggers} = useTriggers()
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [isToggleDialogOpen, setIsToggleDialogOpen] = useState(false)
  const [isConvertDialogOpen, setIsConvertDialogOpen] = useState(false)
  const [isNavigating, setIsNavigating] = useState(false)
  const onRunSuccess = useCallback(() => {
    setIsNavigating(true)
    navigate(`${href}?run=success`)
  }, [navigate, href])
  const {isRunDialogOpen, setIsRunDialogOpen, handleRunClick, isPending, runAutomation, error, resetError} =
    useRunAutomationAction({
      owner: repo.ownerLogin,
      repo: repo.name,
      automation,
      triggerDefinitions: triggers,
      onSuccess: onRunSuccess,
      onError: onRunError,
      disabled: repo.isEmpty,
    })
  const showSpinner = (isPending || isNavigating) && !isRunDialogOpen

  const handleRunNowClick = useCallback(() => {
    onRunStart?.()
    handleRunClick()
  }, [onRunStart, handleRunClick])

  const handleClick = (e: React.MouseEvent) => {
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    if (e.metaKey || e.ctrlKey) return

    e.preventDefault()
    sendEvent('agent_sessions.task_list_item_click', {
      target: 'AUTOMATION',
      task_id: automation.id,
    })
    navigate(href)
  }

  return (
    <SimpleListItem className={styles.item}>
      <ListItemTitle as="a" href={href} onClick={handleClick}>
        {automation.name}
      </ListItemTitle>
      <SimpleListItem.TrailingActions>
        <div className={styles.trailingActionsContent}>
          {automation.disabled && <Label variant="secondary">Disabled</Label>}
          {showSpinner ? (
            <div className={styles.spinnerContainer}>
              <Spinner size="small" />
            </div>
          ) : (
            <IconButton
              icon={PlayIcon}
              aria-label="Run now"
              variant="invisible"
              disabled={repo.isEmpty}
              onClick={handleRunNowClick}
            />
          )}
          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton icon={KebabHorizontalIcon} aria-label="Automation options" variant="invisible" />
            </ActionMenu.Anchor>
            <ActionMenu.Overlay width="auto">
              <ActionList>
                <ActionList.Item onSelect={() => navigate(`${href}/edit`)}>
                  <ActionList.LeadingVisual>
                    <PencilIcon />
                  </ActionList.LeadingVisual>
                  Edit
                </ActionList.Item>
                {automation.disabled ? (
                  <ActionList.Item disabled={repo.isEmpty} onSelect={() => setIsToggleDialogOpen(true)}>
                    <ActionList.LeadingVisual>
                      <PlayIcon />
                    </ActionList.LeadingVisual>
                    Enable automation
                  </ActionList.Item>
                ) : (
                  <ActionList.Item onSelect={() => setIsToggleDialogOpen(true)}>
                    <ActionList.LeadingVisual>
                      <PauseIcon />
                    </ActionList.LeadingVisual>
                    Disable automation
                  </ActionList.Item>
                )}
                <ActionList.Item onSelect={() => setIsConvertDialogOpen(true)}>
                  <ActionList.LeadingVisual>
                    <WorkflowIcon />
                  </ActionList.LeadingVisual>
                  Convert to agentic workflow
                </ActionList.Item>
                <ActionList.Divider />
                <ActionList.Item variant="danger" onSelect={() => setIsDeleteDialogOpen(true)}>
                  <ActionList.LeadingVisual>
                    <TrashIcon />
                  </ActionList.LeadingVisual>
                  Delete automation
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
          {isDeleteDialogOpen && (
            <DeleteAutomationDialog
              automationId={automation.id}
              onDeleted={() => {}}
              onClose={() => setIsDeleteDialogOpen(false)}
            />
          )}
          {isToggleDialogOpen && (
            <ToggleAutomationDialog
              automationId={automation.id}
              disable={!automation.disabled}
              onClose={() => setIsToggleDialogOpen(false)}
              onActiveLimitReached={onActiveLimitReached}
              onAutomationDisabled={onAutomationDisabled}
            />
          )}
          {isConvertDialogOpen && (
            <ConvertToWorkflowDialog automationId={automation.id} onClose={() => setIsConvertDialogOpen(false)} />
          )}
          {isRunDialogOpen && (
            <RunAutomationDialog
              automation={automation}
              triggerDefinitions={triggers}
              runAutomation={runAutomation}
              isPending={isPending}
              error={error}
              resetError={resetError}
              onClose={() => setIsRunDialogOpen(false)}
              onSuccess={onRunSuccess}
            />
          )}
        </div>
      </SimpleListItem.TrailingActions>
    </SimpleListItem>
  )
}
