import {GitHubAvatar} from '@github-ui/github-avatar'
import {ActionList, ActionMenu, Button} from '@primer/react'
import {TriangleDownIcon} from '@primer/octicons-react'
import type {FilterOption} from '../../utils/filter-utils'

export function MultiSelectFilter({
  label,
  selected,
  options,
  onSelectionChange,
  testId,
  className,
  nested,
}: {
  label: string
  selected: string[]
  options: FilterOption[]
  onSelectionChange: (values: string[]) => void
  testId?: string
  className?: string
  nested?: boolean
}) {
  if (options.length === 0) return null

  const handleSelect = (event: React.MouseEvent | React.KeyboardEvent, option: FilterOption) => {
    // Prevent ActionList.Item's afterSelect from firing, which would close the menu
    event.preventDefault()
    const values = option.rawValues ?? [option.value]
    const isSelected = values.some(v => selected.includes(v))
    if (isSelected) {
      onSelectionChange(selected.filter(v => !values.includes(v)))
    } else {
      onSelectionChange([...selected, ...values])
    }
  }

  const selectedCount = options.filter(opt => {
    const values = opt.rawValues ?? [opt.value]
    return values.some(v => selected.includes(v))
  }).length

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        {nested ? (
          <ActionList.Item role="menuitem" aria-label={label}>
            {label}...
          </ActionList.Item>
        ) : (
          <Button
            variant="invisible"
            trailingVisual={TriangleDownIcon}
            className={className}
            data-testid={testId}
            count={selectedCount || undefined}
          >
            {label}
          </Button>
        )}
      </ActionMenu.Anchor>
      <ActionMenu.Overlay width="auto">
        <ActionList selectionVariant="multiple">
          {options.map(opt => (
            <ActionList.Item
              key={opt.value}
              selected={opt.rawValues ? opt.rawValues.some(v => selected.includes(v)) : selected.includes(opt.value)}
              onSelect={e => handleSelect(e, opt)}
            >
              {opt.icon && (
                <ActionList.LeadingVisual>
                  <opt.icon />
                </ActionList.LeadingVisual>
              )}
              {opt.avatarUrl && (
                <ActionList.LeadingVisual>
                  <GitHubAvatar src={opt.avatarUrl} size={20} alt="" />
                </ActionList.LeadingVisual>
              )}
              {opt.label}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
