import {useCallback, useLayoutEffect, useRef} from 'react'

import {useResizeObserver} from '@primer/react'

/**
 * Updates the --app-offset CSS variable based on the repo-agents app's distance from the top of the viewport.
 * This ensures the app properly accounts for elements above it (global header, staffbar, notification banners, etc.).
 * The offset is recalculated when the document body resizes.
 */
export function useUpdateAppOffset(): void {
  const appRef = useRef<HTMLElement | null>(null)
  const bodyRef = useRef<HTMLElement | null>(null)

  const updateOffset = useCallback(() => {
    const offset = appRef.current?.offsetTop ?? 0
    if (appRef.current) {
      appRef.current.style.setProperty('--app-offset', `${offset}px`)
    }
  }, [])

  // Wrapped in requestAnimationFrame to avoid triggering a resize from within the observer callback
  const updateOffsetOnResize = useCallback(() => {
    requestAnimationFrame(updateOffset)
  }, [updateOffset])

  useLayoutEffect(() => {
    appRef.current = document.querySelector('react-app[app-name="repo-agents"]')
    bodyRef.current = document.body
    // Run the handler once on mount to ensure offset is set immediately
    updateOffset()
  }, [updateOffset])

  // Observe the body to catch changes to the offset (e.g., due to a sticky header being dismissed)
  useResizeObserver(updateOffsetOnResize, bodyRef)
}
