import {useMemo} from 'react'
import {ActionMenu, ActionList, Button, CounterLabel} from '@primer/react'
import styles from './AgentFilterButton.module.css'
import {TriangleDownIcon, AgentIcon, TerminalIcon, VscodeIcon} from '@primer/octicons-react'
import type {AgentInfo} from '@github-ui/agent-sessions/types/session'
import type {Icon} from '@primer/octicons-react'

/** Display metadata for known agent groups.
 *  Only groups listed here appear as filter options. */
const GROUP_METADATA: Record<string, {label: string; order: number; icon?: Icon}> = {
  cloud: {label: 'Cloud agents', order: 0, icon: AgentIcon},
  cli: {label: 'CLI', order: 1, icon: TerminalIcon},
  vscode: {label: 'VS Code', order: 2, icon: VscodeIcon},
} satisfies Partial<Record<NonNullable<AgentInfo['group']>, {label: string; order: number; icon?: Icon}>>

interface AgentGroup {
  key: string
  label: string
  icon?: Icon
  agents: AgentInfo[]
}

export interface AgentFilterButtonProps {
  agents: AgentInfo[]
  selectedGroups: string[]
  onSelectionChange: (groups: string[]) => void
  isLoading?: boolean
}

/** Derives sorted agent groups from a flat list of agents */
function useAgentGroups(agents: AgentInfo[]): AgentGroup[] {
  return useMemo(() => {
    const groupMap = new Map<string, AgentInfo[]>()
    for (const agent of agents) {
      const key = agent.group ?? 'cloud'
      const list = groupMap.get(key)
      if (list) {
        list.push(agent)
      } else {
        groupMap.set(key, [agent])
      }
    }

    return Array.from(groupMap.entries())
      .filter(([key]) => key in GROUP_METADATA)
      .map(([key, groupAgents]) => ({
        key,
        label: GROUP_METADATA[key]?.label ?? key,
        icon: GROUP_METADATA[key]?.icon,
        agents: groupAgents,
      }))
      .sort((a, b) => (GROUP_METADATA[a.key]?.order ?? 99) - (GROUP_METADATA[b.key]?.order ?? 99))
  }, [agents])
}

export function AgentFilterButton({agents, selectedGroups, onSelectionChange, isLoading}: AgentFilterButtonProps) {
  const groups = useAgentGroups(agents)

  if (isLoading || groups.length <= 1) {
    return null
  }

  const handleSelect = (groupKey: string) => {
    if (selectedGroups.includes(groupKey)) {
      onSelectionChange(selectedGroups.filter(g => g !== groupKey))
    } else {
      onSelectionChange([...selectedGroups, groupKey])
    }
  }

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        <Button variant="invisible" trailingVisual={TriangleDownIcon} className={styles.filterButton}>
          Type
          {selectedGroups.length > 0 && (
            <>
              {' '}
              <CounterLabel>{selectedGroups.length}</CounterLabel>
            </>
          )}
        </Button>
      </ActionMenu.Anchor>
      <ActionMenu.Overlay width="auto">
        <ActionList selectionVariant="multiple">
          {groups.map(group => (
            <ActionList.Item
              key={group.key}
              selected={selectedGroups.includes(group.key)}
              onSelect={() => handleSelect(group.key)}
            >
              {group.icon && (
                <ActionList.LeadingVisual>
                  <group.icon />
                </ActionList.LeadingVisual>
              )}
              {group.label}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
