/** Query parameter used to identify a suggested automation template on the new automation page. */
export const SUGGESTED_AUTOMATION_QUERY_PARAM = 'template'

/** Resolves formData, calling it if it's a lazy getter. */
export function resolveFormData(suggestion: SuggestedAutomation): Partial<AutomationFormData> {
  return typeof suggestion.formData === 'function' ? suggestion.formData() : suggestion.formData
}

export function getSuggestedAutomation(id: string | null | undefined): SuggestedAutomation | undefined {
  if (!id) return undefined
  return SUGGESTED_AUTOMATIONS.find(s => s.id === id)
}
