import type {ReactNode} from 'react'
import type {AgentAccessState} from './get-agent-access-state'
import type {ActiveTab} from '@github-ui/agent-sessions/types/filter-types'
import {CliEmptyDescription} from './CliEmptyDescription'

interface EmptyStateParams {
  openCount?: number
  closedCount?: number
  activeTab: ActiveTab
  accessState: AgentAccessState
}

export function getEmptyState({openCount, closedCount, activeTab, accessState}: EmptyStateParams): {
  heading: string
  description: ReactNode
} {
  const hasNoSessions = openCount === 0 && closedCount === 0

  if (accessState.kind === 'ccr-only' && hasNoSessions) {
    return {
      heading: 'Let Copilot work on tasks for you in the background.',
      description:
        'Your code review sessions are available from the pull request timeline. Enable Copilot cloud agent to assign tasks, track progress, and review changes — all from this page.',
    }
  }

  if (accessState.kind === 'cli-only' && hasNoSessions) {
    return {
      heading: 'Control your CLI sessions from the web via copilot --remote.',
      description: <CliEmptyDescription cta={accessState.cta} />,
    }
  }

  return {
    heading: hasNoSessions
      ? 'There are no sessions yet'
      : activeTab === 'open'
        ? 'There are no open sessions'
        : 'There are no closed sessions',
    description: 'Let agents work independently in the background to complete tasks, and then monitor their progress.',
  }
}
