import {
  PulseIcon,
  PersonIcon,
  GearIcon,
  InboxIcon,
  CodespacesIcon,
  CodeReviewIcon,
  PlayIcon,
} from '@primer/octicons-react'
import {useLocation} from '@github-ui/react-router'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import {useCurrentRepository} from '@github-ui/current-repository'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useEffect, useMemo, useRef} from 'react'

import {FeedbackListItem} from './feedback/FeedbackListItem'
import styles from './RepoAgentsSidebar.module.css'
import {NavList} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {NudgeCard} from '@github-ui/agent-sessions/components/nudges/NudgeCard'
import {useNudge} from '@github-ui/agent-sessions/hooks/use-nudge'
import {buildSidebarFilterQuery, readFiltersFromSearchParams} from '@github-ui/agent-sessions/utils/session-filter-url'

export interface RepoAgentsSidebarProps {
  /**
   * The current user's login, used for the 'Created by me' filter.
   */
  currentUserLogin: string | undefined
  /**
   * Whether Copilot memory is enabled for this repository.
   */
  copilotMemoryEnabled: boolean
  /**
   * The file path to the copilot-setup-steps.yml file, or null if it doesn't exist.
   */
  copilotSetupStepsFilePath: string | null
  /**
   * Whether the current user has permissions to access CCA settings.
   */
  copilotCodingAgentEnabled: boolean
  /**
   * Whether the current user has CCA access by their own policy.
   */
  userHasCCAByPolicy: boolean
  /**
   * Whether the repository has a .github/agents.md or .github/copilot-instructions.md file.
   */
  hasAgentsMd: boolean
  /**
   * Whether the Automations area is visible. Server-resolved boolean; the
   * Automations tab is only shown when this is strictly `true`.
   */
  automationsVisible?: boolean
}

/**
 * Sidebar navigation for filtering repo agent sessions.
 * Provides "All sessions" and "Created by me" filter options.
 */
export function RepoAgentsSidebar({
  currentUserLogin,
  copilotMemoryEnabled,
  copilotSetupStepsFilePath,
  copilotCodingAgentEnabled,
  userHasCCAByPolicy,
  hasAgentsMd,
  automationsVisible,
}: RepoAgentsSidebarProps) {
  const [searchParams, setSearchParams] = useSearchParams()
  const navigate = useNavigate()
  const location = useLocation()
  const repo = useCurrentRepository()
  const owner = repo.ownerLogin
  const repoName = repo.name
  const agentsBasePath = `/${owner}/${repoName}/agents`

  const {
    activeNudge,
    dismiss: dismissNudge,
    dismissAll: dismissAllNudges,
    trackImpression,
    trackClick,
    goToNext,
    goToPrev,
    totalCount,
  } = useNudge('agents_tab_below_input', {hasAgentsMd})

  // Copilot settings URLs
  const copilotSettingsBaseUrl = `/${owner}/${repoName}/settings/copilot`
  const ccaSettingsUrl = `${copilotSettingsBaseUrl}/coding_agent`
  const memorySettingsUrl = `${copilotSettingsBaseUrl}/memory`

  // Determine visibility of footer items
  const showMemories = copilotMemoryEnabled
  const showConfigure = copilotCodingAgentEnabled

  // Feature flag for q= syntax
  const useQSyntax = isFeatureEnabled('copilot_mission_control_session_filters')

  // Parse the unified ?q= param for sidebar state detection
  const parsedFilters = useMemo(
    () => readFiltersFromSearchParams(searchParams, currentUserLogin),
    [searchParams, currentUserLogin],
  )
  const typeFilter = searchParams.get('type')
  const qParam = searchParams.get('q')
  const authorParam = searchParams.get('author')

  // Detect sidebar state from the parsed ?q= filters (works for both modes via backward compat)
  const isOnAgentsPage = location.pathname === agentsBasePath
  const showNeedsAttentionTab = isFeatureEnabled('copilot_mission_control_needs_attention')
  const isShowingNeedsAttention =
    showNeedsAttentionTab &&
    isOnAgentsPage &&
    parsedFilters.detailedStatuses.length === 1 &&
    parsedFilters.detailedStatuses[0] === 'needs_attention' &&
    parsedFilters.status === 'open' &&
    currentUserLogin !== undefined &&
    parsedFilters.creators.length === 1 &&
    parsedFilters.creators[0] === currentUserLogin
  const isFilteredByCurrentUser = currentUserLogin
    ? isOnAgentsPage &&
      parsedFilters.excludedCreators.length === 0 &&
      typeFilter === null &&
      !isShowingNeedsAttention &&
      ((parsedFilters.creators.length === 1 && parsedFilters.creators[0] === currentUserLogin) ||
        (qParam === null && authorParam === null && typeFilter === null))
    : false
  // All sessions: no author filter (or explicit all)
  const isShowingAllSessions =
    isOnAgentsPage &&
    typeFilter === null &&
    !isShowingNeedsAttention &&
    (useQSyntax
      ? (parsedFilters.creators.length === 0 && qParam !== null) ||
        parsedFilters.excludedCreators.length > 0 ||
        (parsedFilters.creators.length > 0 && parsedFilters.creators[0] !== currentUserLogin)
      : authorParam === '*')
  const isShowingCodeReviews = isOnAgentsPage && typeFilter === 'review'
  const showCodeReviewsTab = isFeatureEnabled('copilot_mission_control_code_review_tab')
  const isShowingAutomations = location.pathname.startsWith(`${agentsBasePath}/automations`)
  const showAutomationsTab = automationsVisible === true

  // Track if this is the initial page load to avoid redirecting after user clicks "All sessions"
  const hasRedirectedRef = useRef(false)

  // Redirect to "Created by me" only on initial page load when there's no filter params
  useEffect(() => {
    // Don't redirect if any filter param is present (q= or legacy)
    const hasNoFilter = useQSyntax
      ? qParam === null && typeFilter === null && authorParam === null
      : authorParam === null && typeFilter === null
    if (isOnAgentsPage && currentUserLogin && hasNoFilter && !hasRedirectedRef.current) {
      hasRedirectedRef.current = true
      if (useQSyntax) {
        const q = buildSidebarFilterQuery({status: 'open', creators: [currentUserLogin], currentUserLogin})
        setSearchParams(
          params => {
            params.set('q', q)
            return params
          },
          {replace: true},
        )
      } else {
        setSearchParams(
          params => {
            params.set('author', currentUserLogin)
            return params
          },
          {replace: true},
        )
      }
    }
  }, [isOnAgentsPage, currentUserLogin, qParam, authorParam, typeFilter, setSearchParams, useQSyntax])

  // Build sidebar navigation URLs based on feature flag
  function buildSidebarUrl(filter: {creators?: string[]; detailedStatuses?: string[]; type?: string}): string {
    if (filter.type) {
      return `${agentsBasePath}?type=${filter.type}`
    }
    if (useQSyntax) {
      const q = buildSidebarFilterQuery({
        status: 'open',
        creators: filter.creators,
        detailedStatuses: filter.detailedStatuses,
        currentUserLogin,
      })
      const params = new URLSearchParams()
      params.set('q', q)
      return `${agentsBasePath}?${params.toString()}`
    }
    // Legacy mode
    const params = new URLSearchParams()
    if (filter.creators && filter.creators.length > 0) {
      params.set('author', filter.creators[0] ?? '')
    } else {
      params.set('author', '*')
    }
    if (filter.detailedStatuses?.includes('needs_attention')) {
      params.set('status', 'needs_attention')
    }
    return `${agentsBasePath}?${params.toString()}`
  }

  const handleShowAllSessions = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    hasRedirectedRef.current = true
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'ALL_SESSIONS'})
    navigate(buildSidebarUrl({creators: []}))
  }

  const handleShowMySessions = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    if (currentUserLogin) {
      sendEvent('agent_sessions.sidebar_tab_click', {target: 'CREATED_BY_ME'})
      navigate(buildSidebarUrl({creators: [currentUserLogin]}))
    }
  }

  const handleShowNeedsAttention = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    hasRedirectedRef.current = true
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'NEEDS_ATTENTION'})
    navigate(
      buildSidebarUrl({creators: currentUserLogin ? [currentUserLogin] : [], detailedStatuses: ['needs_attention']}),
    )
  }

  const handleShowCodeReviews = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    hasRedirectedRef.current = true
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'CODE_REVIEWS'})
    navigate(buildSidebarUrl({type: 'review'}))
  }

  const handleShowAutomations = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    hasRedirectedRef.current = true
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'AUTOMATIONS'})
    navigate(`${agentsBasePath}/automations`)
  }

  // Create URLs for each filter option
  const allSessionsHref = buildSidebarUrl({creators: []})
  const mySessionsHref = currentUserLogin ? buildSidebarUrl({creators: [currentUserLogin]}) : agentsBasePath
  const needsAttentionHref = buildSidebarUrl({
    creators: currentUserLogin ? [currentUserLogin] : [],
    detailedStatuses: ['needs_attention'],
  })
  const codeReviewsHref = buildSidebarUrl({type: 'review'})
  const automationsHref = `${agentsBasePath}/automations`

  return (
    <div className={styles.sidebarContainer}>
      <NavList aria-label="Session filters">
        {currentUserLogin && (
          <NavList.Item
            href={mySessionsHref}
            aria-current={isFilteredByCurrentUser ? 'page' : undefined}
            onClick={handleShowMySessions}
          >
            <NavList.LeadingVisual>
              <PersonIcon />
            </NavList.LeadingVisual>
            Created by me
          </NavList.Item>
        )}
        {showNeedsAttentionTab && (
          <NavList.Item
            href={needsAttentionHref}
            aria-current={isShowingNeedsAttention ? 'page' : undefined}
            onClick={handleShowNeedsAttention}
          >
            <NavList.LeadingVisual>
              <InboxIcon />
            </NavList.LeadingVisual>
            Needs attention
          </NavList.Item>
        )}
        {userHasCCAByPolicy && (
          <NavList.Item
            href={allSessionsHref}
            aria-current={isShowingAllSessions ? 'page' : undefined}
            onClick={handleShowAllSessions}
          >
            <NavList.LeadingVisual>
              <PulseIcon />
            </NavList.LeadingVisual>
            All sessions
          </NavList.Item>
        )}
        {showCodeReviewsTab && (
          <NavList.Item
            href={codeReviewsHref}
            aria-current={isShowingCodeReviews ? 'page' : undefined}
            onClick={handleShowCodeReviews}
          >
            <NavList.LeadingVisual>
              <CodeReviewIcon />
            </NavList.LeadingVisual>
            Code reviews
          </NavList.Item>
        )}
        {showAutomationsTab && (
          <NavList.Item
            href={automationsHref}
            aria-current={isShowingAutomations ? 'page' : undefined}
            onClick={handleShowAutomations}
          >
            <NavList.LeadingVisual>
              <PlayIcon />
            </NavList.LeadingVisual>
            Automations
          </NavList.Item>
        )}
      </NavList>

      {isFeatureEnabled('copilot_mc_nudges') && activeNudge && (
        <div className={styles.sidebarNudge}>
          <NudgeCard
            nudge={activeNudge}
            onDismiss={dismissNudge}
            onDismissAll={dismissAllNudges}
            onImpression={trackImpression}
            onClick={trackClick}
            onNext={goToNext}
            onPrev={goToPrev}
            totalCount={totalCount}
            compact
          />
        </div>
      )}

      <NavList aria-label="Agent management" className={styles.footerActions}>
        <NavList.Divider />
        {showConfigure && (
          <NavList.Item href={ccaSettingsUrl}>
            <NavList.LeadingVisual>
              <GearIcon />
            </NavList.LeadingVisual>
            Configure
          </NavList.Item>
        )}
        {showMemories && (
          <NavList.Item href={memorySettingsUrl}>
            <NavList.LeadingVisual>
              <InboxIcon />
            </NavList.LeadingVisual>
            Memories
          </NavList.Item>
        )}
        {copilotSetupStepsFilePath && (
          <NavList.Item href={copilotSetupStepsFilePath}>
            <NavList.LeadingVisual>
              <CodespacesIcon />
            </NavList.LeadingVisual>
            Customize environment
          </NavList.Item>
        )}
        <FeedbackListItem />
      </NavList>
    </div>
  )
}
