import {useRef} from 'react'
import {CommentDiscussionIcon} from '@primer/octicons-react'
import {type RatingOption, frustratedIcon, frownIcon, smileIcon, grinIcon} from '@github-ui/user-feedback'
import {useFeedbackDialog} from '@github-ui/agent-sessions/components/task-view/feedback/useFeedbackDialog'
import {NavList} from '@primer/react'

import styles from './FeedbackListItem.module.css'

const ratingOptions: Array<RatingOption<'VERY_NEGATIVE' | 'NEGATIVE' | 'POSITIVE' | 'VERY_POSITIVE'>> = [
  {
    name: 'Hate it',
    value: 'VERY_NEGATIVE' as const,
    icon: frustratedIcon,
    color: 'veryDissatisfied',
  },
  {
    name: 'Not great',
    value: 'NEGATIVE' as const,
    icon: frownIcon,
    color: 'dissatisfied',
  },
  {
    name: "It's ok",
    value: 'POSITIVE' as const,
    icon: smileIcon,
    color: 'satisfied',
  },
  {
    name: 'Love it',
    value: 'VERY_POSITIVE' as const,
    icon: grinIcon,
    color: 'verySatisfied',
  },
]

export function FeedbackListItem() {
  const {openFeedback, FeedbackDialog} = useFeedbackDialog('sidebar', ratingOptions)
  const returnFocusRef = useRef<HTMLButtonElement>(null)

  return (
    <>
      <NavList.Item className={styles.FeedbackItem} as="button" onClick={() => openFeedback()} ref={returnFocusRef}>
        <NavList.LeadingVisual>
          <CommentDiscussionIcon />
        </NavList.LeadingVisual>
        Give feedback
      </NavList.Item>
      <FeedbackDialog returnFocusRef={returnFocusRef} />
    </>
  )
}
