import {useQuery} from '@github-ui/react-query'
import {fetchCAPI} from '../utils/fetch-capi'

interface TaskCreator {
  id: number
  login?: string
  node_id?: string
  url?: string
}

interface ListTaskCreatorsResponse {
  creators: TaskCreator[]
}

/**
 * Fetches the list of users who have created tasks in a repository.
 * Calls the CMC `/agents/repos/{owner}/{repo}/tasks/creators` endpoint via CAPI.
 */
export function useTaskCreators(owner: string, repo: string, enabled = true) {
  // eslint-disable-next-line @github-ui/github-monorepo/require-query-persister -- Creator list is permission-sensitive (viewer-scoped) and short-lived; should refetch rather than restore stale data.
  return useQuery({
    queryKey: ['taskCreators', owner, repo],
    queryFn: async () => {
      const path = `/agents/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/tasks/creators`
      const response = await fetchCAPI({path})
      const data = (await response.json()) as ListTaskCreatorsResponse
      return data.creators
    },
    enabled: enabled && !!owner && !!repo,
    staleTime: 5 * 60 * 1000, // 5 minutes — matches CMC cache TTL
  })
}
