import {ssrSafeLocation} from '@github-ui/ssr-utils'
import type {Repository} from '@github-ui/current-repository'

/**
 * Returns the relative path for an automation detail page.
 */
export function getAutomationPath(repo: Pick<Repository, 'ownerLogin' | 'name'>, automationId: string): string {
  return `/${repo.ownerLogin}/${repo.name}/agents/automations/${encodeURIComponent(automationId)}`
}

/**
 * Returns the full URL for an automation, suitable for CLI commands like `gh aw add`.
 */
export function getAutomationUrl(repo: Pick<Repository, 'ownerLogin' | 'name'>, automationId: string): string {
  const origin = ssrSafeLocation.origin || 'https://github.com'
  return `${origin}/${repo.ownerLogin}/${repo.name}/agents/automations/${encodeURIComponent(automationId)}`
}
