import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {useCurrentRepository} from '@github-ui/current-repository'
import {Dialog, Link} from '@primer/react'
import {clsx} from 'clsx'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {getAutomationUrl} from './automation-paths'
import styles from './ConvertToWorkflowDialog.module.css'

interface ConvertToWorkflowDialogProps {
  automationId: string
  onClose: () => void
}

export function ConvertToWorkflowDialog({automationId, onClose}: ConvertToWorkflowDialogProps) {
  const repo = useCurrentRepository()
  const command = useMemo(() => {
    return `gh aw add ${getAutomationUrl(repo, automationId)}`
  }, [repo, automationId])

  const [isScrolling, setIsScrolling] = useState(false)
  const scrollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const handleScroll = useCallback(() => {
    setIsScrolling(true)
    if (scrollTimerRef.current) {
      clearTimeout(scrollTimerRef.current)
    }
    scrollTimerRef.current = setTimeout(() => {
      setIsScrolling(false)
    }, 800)
  }, [])

  useEffect(() => {
    return () => {
      if (scrollTimerRef.current) {
        clearTimeout(scrollTimerRef.current)
        scrollTimerRef.current = null
      }
    }
  }, [])

  return (
    <Dialog
      onClose={onClose}
      width="xlarge"
      title={
        <span>
          Convert to agentic workflow with the <code className={styles.titleCode}>gh aw</code> CLI tool
        </span>
      }
    >
      <div className={styles.body}>
        <p className={styles.description}>
          With agentic workflows installed locally (view{' '}
          <Link
            inline
            href="https://github.github.com/gh-aw/setup/quick-start/"
            target="_blank"
            rel="noopener noreferrer"
          >
            quickstart
          </Link>
          ), run the following command to compile this automation into a workflow:
        </p>
        <div className={styles.codeBlockWrapper}>
          <pre className={styles.codeBlock} onScroll={handleScroll}>
            <code>{command}</code>
          </pre>
          <span className={clsx(styles.copyButtonWrapper, isScrolling && styles.copyButtonHidden)}>
            <CopyToClipboardButton textToCopy={command} ariaLabel="Copy command to clipboard" variant="default" />
          </span>
        </div>
      </div>
    </Dialog>
  )
}
