import {useMutation, useQueryClient} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import {buildTriggerObject} from '@github-ui/automation-form'
import type {AutomationFormData} from '@github-ui/automation-form'
import type {Automation, AutomationDetail} from '../types/automations-payload'

interface UseCreateAutomationArgs {
  owner: string
  repo: string
}

export function useCreateAutomation({owner, repo}: UseCreateAutomationArgs) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationKey: ['createAutomation', owner, repo],
    mutationFn: async (data: AutomationFormData): Promise<AutomationDetail | null> => {
      const triggers = buildTriggerObject(data.triggers)

      const response = await fetchCAPI({
        path: `/agents/repos/${owner}/${repo}/automations`,
        method: 'POST',
        body: {
          name: data.name,
          description: data.description,
          prompt: data.prompt,
          model: data.model,
          require_actor_write_permission: data.requireActorWritePermission,
          ...(triggers && {triggers}),
          ...(data.tools.length > 0 && {tools: data.tools}),
        },
      })

      // The create endpoint normally returns the created automation as JSON.
      // Fall back to null if the body is empty or unparseable so we still
      // invalidate the list and let the next fetch reconcile.
      try {
        const parsed = (await response.json()) as AutomationDetail
        return parsed && typeof parsed === 'object' && 'id' in parsed ? parsed : null
      } catch {
        return null
      }
    },
    onSuccess: created => {
      // Seed the list cache with the server-confirmed automation so it shows
      // up immediately on the list page, even when the backend list endpoint
      // is eventually consistent and would otherwise omit it on the first
      // post-redirect fetch.
      if (created) {
        queryClient.setQueryData<Automation[]>(['automations', owner, repo], prev =>
          prev ? [created, ...prev.filter(a => a.id !== created.id)] : [created],
        )
      }
      // Invalidate so a background refetch eventually reconciles with the server.
      queryClient.invalidateQueries({queryKey: ['automations', owner, repo]})
    },
  })
}
