import {useCAPIQuery} from '@github-ui/agent-sessions/hooks/useCAPIQuery'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import type {APITask} from '@github-ui/agent-sessions/types/api-task'
import type {UITask} from '@github-ui/agent-sessions/types/task'
import {transformAPITasksToUnhydrated} from '@github-ui/agent-sessions/utils/task-helpers'
import {usePullRequests} from '@github-ui/agent-sessions/hooks/usePullRequests'
import {useCallback, useMemo} from 'react'
import {
  useAgentSessionsAlive,
  type AgentSessionAlivePayload,
} from '@github-ui/agent-sessions/hooks/use-agent-sessions-alive'
import {useDebounce} from '@github-ui/use-debounce'
import {useQueryClient} from '@github-ui/react-query'

export const automationTasksQueryKey = (automationId?: string) => ['automationTasks', automationId]

export async function fetchAutomationTasks(automationId: string): Promise<APITask[]> {
  const response = await fetchCAPI({path: `/agents/automations/${encodeURIComponent(automationId)}/tasks`})
  const data = await response.json()
  return data.tasks as APITask[]
}

export function useAutomationTasks({
  automationId,
  initialData,
  repoId,
}: {
  automationId?: string
  initialData?: APITask[]
  repoId?: number
}) {
  const queryClient = useQueryClient()

  const handleAliveUpdate = useCallback(
    (payload?: AgentSessionAlivePayload) => {
      if (repoId !== undefined && payload?.repo_id !== undefined && payload.repo_id !== repoId) {
        return
      }
      queryClient.invalidateQueries({
        queryKey: automationTasksQueryKey(automationId),
      })
    },
    [queryClient, automationId, repoId],
  )

  const debouncedHandleAliveUpdate = useDebounce(handleAliveUpdate, 3000, {maxWait: 10000})

  useAgentSessionsAlive({
    onEvent: debouncedHandleAliveUpdate,
    enableCreateEvents: false,
    enableUpdateEvents: !!automationId,
    enableLogUpdates: false,
    enableTaskUpdates: !!automationId,
    enabled: !!automationId,
  })

  const {data, isLoading, isError} = useCAPIQuery<APITask[]>({
    queryKey: automationTasksQueryKey(automationId),
    queryFn: () => {
      if (!automationId) {
        throw new Error('automationId is required')
      }
      return fetchAutomationTasks(automationId)
    },
    initialData: initialData ?? undefined,
    enabled: !!automationId,
  })

  const unhydratedTasks = useMemo(() => (data ? transformAPITasksToUnhydrated(data) : []), [data])
  const {data: prMap = {}} = usePullRequests({
    tasks: unhydratedTasks,
    refetchOnMount: true,
  })

  const tasks: UITask[] = useMemo(
    () =>
      unhydratedTasks.map(task => ({
        ...task,
        pull: task.resource_id ? prMap[task.resource_id] : undefined,
      })),
    [unhydratedTasks, prMap],
  )

  return {
    tasks,
    isLoading,
    isError,
  }
}
