import {useMutation, useQueryClient} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'

interface UseDeleteAutomationArgs {
  owner: string
  repo: string
  automationId?: string
}

export function useDeleteAutomation({owner, repo, automationId}: UseDeleteAutomationArgs) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationKey: ['deleteAutomation', owner, repo, automationId],
    mutationFn: async () => {
      if (!automationId) {
        throw new Error('automationId is required')
      }

      const response = await fetchCAPI({
        path: `/agents/repos/${owner}/${repo}/automations/${encodeURIComponent(automationId)}`,
        method: 'DELETE',
      })
      return response
    },
    onSuccess: () => {
      queryClient.invalidateQueries({queryKey: ['automations', owner, repo]})
    },
  })
}
