import {setTitle} from '@github-ui/document-metadata'
import {useCurrentRepository} from '@github-ui/current-repository'
import {Banner, Button, Heading} from '@primer/react'
import {useNavigate} from '@github-ui/use-navigate'
import {Navigate, useLocation} from '@github-ui/react-router'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import styles from './RepoAgentsView.module.css'
import automationStyles from './AutomationsView.module.css'
import {AutomationsList} from './AutomationsList'
import {useAutomations} from '../../hooks/use-automations'
import {automationsRoute} from '../../routes/automations-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {AutomationsBlankslate} from './AutomationsBlankslate'
import {SUGGESTED_AUTOMATIONS, SUGGESTED_AUTOMATION_QUERY_PARAM, resolveFormData} from './suggested-automations'
import {AgentIcebreakers} from '@github-ui/agent-sessions/components/agents-view/AgentIcebreakers'
import {useIcebreakers} from '@github-ui/agent-sessions/hooks/use-icebreakers'
import type {IcebreakerOption} from '@github-ui/agent-sessions/types/icebreaker'
import {ActiveLimitReachedBanner, type AutomationsLocationState} from './ActiveLimitReachedBanner'
import {EMPTY_REPO_NOTICE} from '@github-ui/automation-form'

/**
 * Automations view for the repo agents page.
 * Displays automations (triggered custom agents) for a specific repository.
 */
export function AutomationsView() {
  const {data: payload} = useRouteQuery(automationsRoute, 'mainQuery')
  const repository = useCurrentRepository()
  const {currentUserCanPush, isEmpty} = repository
  const automationsAllowed = payload.automationsVisible !== false
  const {automations, isLoading, isError} = useAutomations(
    repository.ownerLogin,
    repository.name,
    payload.automations,
    automationsAllowed,
  )
  const navigate = useNavigate()
  const location = useLocation()
  const navigatedFromCappedCreate = (location.state as AutomationsLocationState | null)?.activeLimitReached === true
  const [cappedOnEnable, setCappedOnEnable] = useState(false)
  const [bannerDismissed, setBannerDismissed] = useState(false)
  const [bannerFocusKey, setBannerFocusKey] = useState(0)
  const showActiveLimitBanner = (navigatedFromCappedCreate || cappedOnEnable) && !bannerDismissed
  const bannerRef = useRef<HTMLElement>(null)
  const handleActiveLimitReached = useCallback(() => {
    setCappedOnEnable(true)
    setBannerDismissed(false)
    setBannerFocusKey(key => key + 1)
  }, [])
  const handleAutomationDisabled = useCallback(() => {
    setCappedOnEnable(false)
    setBannerDismissed(true)
  }, [])

  useEffect(() => {
    if (showActiveLimitBanner) bannerRef.current?.focus()
  }, [showActiveLimitBanner, bannerFocusKey])
  const newAutomationHref = `/${repository.ownerLogin}/${repository.name}/agents/automations/new`
  const suggestedAutomationsEnabled = isFeatureEnabled('copilot_automations_suggested_automations')

  const suggestedItems: IcebreakerOption[] = useMemo(
    () =>
      SUGGESTED_AUTOMATIONS.map(s => {
        const data = resolveFormData(s)
        return {
          title: data.name ?? '',
          subheader: data.description ?? '',
          icon: <s.icon size={16} className="fgColor-muted" />,
          prompt: s.id,
        }
      }),
    [],
  )

  const handleSuggestionNavigate = useCallback(
    (option: IcebreakerOption) => {
      const href = `${newAutomationHref}?${SUGGESTED_AUTOMATION_QUERY_PARAM}=${option.prompt}`
      navigate(href)
    },
    [navigate, newAutomationHref],
  )

  const {
    visible: suggestionsVisible,
    handleSelect: handleSuggestionSelect,
    handleDismiss: handleSuggestionDismiss,
  } = useIcebreakers({
    location: 'automations_page',
    dismissedKey: 'AUTOMATION_SUGGESTIONS_DISMISSED',
    onSelect: handleSuggestionNavigate,
  })

  useEffect(() => {
    setTitle(`Automations · ${repository.nameWithOwner}`)
  }, [repository.nameWithOwner])

  if (!automationsAllowed) {
    return <Navigate to={`/${repository.ownerLogin}/${repository.name}/agents`} replace />
  }

  return (
    <div className={styles.container} data-hpc>
      <div className={styles.content}>
        <>
          <header className={automationStyles.header}>
            <div>
              <Heading as="h2" className={styles.title}>
                Automations
              </Heading>
              <div className={automationStyles.subtitle}>
                Set up personal automations that run on a schedule or in response to events like new issues or updated
                pull requests.
              </div>
            </div>
            {currentUserCanPush &&
              (isEmpty ? (
                <Button variant="primary" disabled>
                  Create new
                </Button>
              ) : (
                <Button
                  as="a"
                  href={newAutomationHref}
                  variant="primary"
                  onClick={(e: React.MouseEvent) => {
                    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
                    if (e.metaKey || e.ctrlKey) return
                    e.preventDefault()
                    navigate(newAutomationHref)
                  }}
                >
                  Create new
                </Button>
              ))}
          </header>
          {isEmpty && (
            <div className={automationStyles.bannerWrapper}>
              <Banner variant="warning" title={EMPTY_REPO_NOTICE.title}>
                {EMPTY_REPO_NOTICE.description}
              </Banner>
            </div>
          )}
          {currentUserCanPush && !isEmpty && suggestedAutomationsEnabled && suggestionsVisible && (
            <AgentIcebreakers
              heading="Suggested automations"
              items={suggestedItems}
              onSelect={handleSuggestionSelect}
              onDismiss={handleSuggestionDismiss}
            />
          )}
          {showActiveLimitBanner && (
            <div className={automationStyles.bannerWrapper}>
              <ActiveLimitReachedBanner ref={bannerRef} onDismiss={() => setBannerDismissed(true)} />
            </div>
          )}
          {!isLoading && !isError && automations.length === 0 ? (
            <AutomationsBlankslate />
          ) : (
            <AutomationsList
              automations={automations}
              isLoading={isLoading}
              isError={isError}
              onActiveLimitReached={handleActiveLimitReached}
              onAutomationDisabled={handleAutomationDisabled}
            />
          )}
        </>
      </div>
    </div>
  )
}
