import type {ReactNode} from 'react'
import {Link} from '@primer/react'
import styles from './RepoTaskList.module.css'

export function CliEmptyDescription({cta}: {cta: 'contact-admin' | 'enable' | 'upgrade'}) {
  let ctaContent: ReactNode
  switch (cta) {
    case 'contact-admin':
      ctaContent = 'contact your administrator to enable Copilot cloud agent.'
      break
    case 'enable':
      ctaContent = (
        <>
          <Link inline href="https://github.com/settings/copilot/coding_agent">
            here
          </Link>{' '}
          to enable Copilot cloud agent.
        </>
      )
      break
    case 'upgrade':
      ctaContent = (
        <>
          <Link inline href="https://github.com/github-copilot/pro">
            here
          </Link>{' '}
          to start a free trial of Copilot cloud agent.
        </>
      )
      break
  }

  return (
    <span className={styles.cliEmptyDescription}>
      You have not created any sessions yet. Click{' '}
      <Link inline href="https://docs.github.com/copilot/how-tos/copilot-cli/steer-remotely">
        here
      </Link>{' '}
      to learn more about --remote or {ctaContent}
    </span>
  )
}
