import {useQuery} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import type {ToolGroup} from './tool-definitions'

async function fetchToolGroups(): Promise<ToolGroup[]> {
  const response = await fetchCAPI({path: '/agents/automations/tools'})
  if (!response.ok) {
    throw new Error(`Failed to fetch tool definitions: ${response.status}`)
  }
  const data = await response.json()
  const groups = Array.isArray(data) ? data : (data.tool_groups ?? data.toolGroups ?? [])
  return groups as ToolGroup[]
}

export function useToolGroups(initialData?: ToolGroup[]) {
  const {data, isLoading, error} = useQuery<ToolGroup[]>({
    queryKey: ['automation-tool-groups'],
    queryFn: fetchToolGroups,
    enabled: !initialData || initialData.length === 0,
    initialData,
  })
  return {toolGroups: data ?? [], loading: isLoading, error}
}
