import {useQuery} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import type {Trigger} from './types'

async function fetchTriggers(): Promise<Trigger[]> {
  const response = await fetchCAPI({path: '/agents/automations/triggers'})
  if (!response.ok) {
    throw new Error(`Failed to fetch triggers: ${response.status}`)
  }
  const data = await response.json()
  return Array.isArray(data) ? data : (data.triggers ?? [])
}

export function useTriggers(initialData?: Trigger[]) {
  const {data, isLoading, error} = useQuery<Trigger[]>({
    queryKey: ['automation-triggers'],
    queryFn: fetchTriggers,
    enabled: !initialData || initialData.length === 0,
    initialData,
  })
  return {triggers: data ?? [], loading: isLoading, error}
}
