import {setTitle} from '@github-ui/document-metadata'
import {useCurrentRepository} from '@github-ui/current-repository'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import {Navigate} from '@github-ui/react-router'
import {useCallback, useEffect} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {newAutomationRoute} from '../../routes/automations-route'
import {useCreateAutomation} from '../../hooks/use-create-automation'

import styles from './RepoAgentsView.module.css'
import {AutomationForm, EMPTY_REPO_NOTICE} from '@github-ui/automation-form'
import type {AutomationFormData} from '@github-ui/automation-form'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {getSuggestedAutomation, resolveFormData, SUGGESTED_AUTOMATION_QUERY_PARAM} from './suggested-automations'
import {getAutomationPath} from './automation-paths'

/**
 * Page view for creating a new automation.
 * Wraps the reusable AutomationForm with page-level layout and navigation.
 */
export function NewAutomationView() {
  const {data: payload} = useRouteQuery(newAutomationRoute, 'mainQuery')
  const repository = useCurrentRepository()
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const backHref = `/${repository.ownerLogin}/${repository.name}/agents/automations`
  const suggestedAutomation = isFeatureEnabled('copilot_automations_suggested_automations')
    ? getSuggestedAutomation(searchParams.get(SUGGESTED_AUTOMATION_QUERY_PARAM))
    : undefined

  const {mutateAsync: createAutomation} = useCreateAutomation({
    owner: repository.ownerLogin,
    repo: repository.name,
  })

  useEffect(() => {
    setTitle(`New Automation · ${repository.nameWithOwner}`)
  }, [repository.nameWithOwner])

  const handleSubmit = useCallback(
    async (data: AutomationFormData) => {
      const result = await createAutomation(data)
      if (result?.id) {
        navigate(getAutomationPath(repository, result.id))
        return
      }
      navigate(backHref, result?.active_limit_reached ? {state: {activeLimitReached: true}} : undefined)
    },
    [createAutomation, navigate, repository, backHref],
  )

  if (payload.automationsVisible === false) {
    return <Navigate to={`/${repository.ownerLogin}/${repository.name}/agents`} replace />
  }

  return (
    <div className={styles.container} data-hpc>
      <div className={styles.content}>
        <AutomationForm
          heading="New automation"
          subtitle="Create a new automation to run on a schedule or in response to events like new issues or updated pull requests."
          onCancel={() => navigate(backHref)}
          onSubmit={handleSubmit}
          initialData={suggestedAutomation ? resolveFormData(suggestedAutomation) : undefined}
          initialTriggers={payload.triggers}
          initialToolGroups={payload.tools}
          orgAllowReadAccessTriggers={payload.orgAllowReadAccessTriggers}
          repoAllowReadAccessTriggers={payload.repoAllowReadAccessTriggers}
          submitDisabledNotice={repository.isEmpty ? EMPTY_REPO_NOTICE : undefined}
        />
      </div>
    </div>
  )
}
