import {useMutation} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'

interface RunAutomationRequest {
  event: string
  type?: string
  conclusion?: string
  resource_url?: string
}

interface UseRunAutomationArgs {
  owner: string
  repo: string
  automationId: string
}

export type RunAutomationMutation = ReturnType<typeof useRunAutomation>

export function useRunAutomation({owner, repo, automationId}: UseRunAutomationArgs) {
  return useMutation({
    mutationKey: ['runAutomation', owner, repo, automationId],
    mutationFn: async (request: RunAutomationRequest) => {
      const response = await fetchCAPI({
        path: `/agents/repos/${owner}/${repo}/automations/${encodeURIComponent(automationId)}/tasks`,
        method: 'POST',
        body: request,
      })

      return response.json()
    },
  })
}
