import {Banner, Button, Dialog, FormControl, Select, TextInput} from '@primer/react'
import {useMemo, useState} from 'react'
import {useCurrentRepository} from '@github-ui/current-repository'
import type {Automation} from '../../types/automations-payload'
import type {Trigger} from '@github-ui/automation-form/types'
import type {RunAutomationMutation} from '../../hooks/use-run-automation'
import styles from './RunAutomationDialog.module.css'

interface RunAutomationDialogProps {
  automation: Automation
  triggerDefinitions: Trigger[]
  runAutomation: RunAutomationMutation['mutate']
  isPending: boolean
  error: Error | null
  resetError: () => void
  onClose: () => void
  onSuccess?: () => void
  onError?: (message: string) => void
}

const NO_EVENT_URL_TRIGGERS = new Set(['interval', 'manual'])

export function RunAutomationDialog({
  automation,
  triggerDefinitions,
  runAutomation,
  isPending,
  error,
  resetError,
  onClose,
  onSuccess,
  onError,
}: RunAutomationDialogProps) {
  const repo = useCurrentRepository()
  const nwo = `${repo.ownerLogin}/${repo.name}`

  const titleMap = useMemo(() => {
    const map: Record<string, string> = {manual: 'Manual'}
    for (const def of triggerDefinitions) {
      map[def.name] = def.title
    }
    return map
  }, [triggerDefinitions])

  const triggerKeys = Object.keys(automation.triggers ?? {})
  const eventTriggers = triggerKeys.filter(t => t !== 'interval')
  const hasInterval = triggerKeys.includes('interval')
  const options = [...eventTriggers, ...(hasInterval ? ['interval'] : []), 'manual']
  const [selectedIndex, setSelectedIndex] = useState(0)
  const selectedEvent = options[selectedIndex] ?? 'manual'
  const [resourceUrl, setResourceUrl] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const isRunning = isPending || submitted

  const placeholders: Record<string, string> = {
    issues: `https://github.com/${nwo}/issues/123`,
    pull_request_opened: `https://github.com/${nwo}/pull/123`,
    pull_request_synchronize: `https://github.com/${nwo}/pull/123`,
    pull_request_merged: `https://github.com/${nwo}/pull/123`,
    workflow_run: `https://github.com/${nwo}/actions/runs/123`,
  }

  const handleRun = () => {
    resetError()
    setSubmitted(true)
    const triggerConfig = automation.triggers?.[selectedEvent]
    // TODO: When the API supports multiple types/conclusions, we should allow the
    // user to select which one to use instead of just picking the first one (since
    // they're 1:1 for now this is fine)
    const type = triggerConfig?.types?.[0]
    const conclusion = triggerConfig?.conclusions?.[0]

    runAutomation(
      {
        event: selectedEvent,
        ...(type ? {type} : {}),
        ...(conclusion ? {conclusion} : {}),
        ...(resourceUrl && !NO_EVENT_URL_TRIGGERS.has(selectedEvent) ? {resource_url: resourceUrl} : {}),
      },
      {
        onSuccess: () => {
          onSuccess?.()
        },
        onError: (err: Error) => {
          setSubmitted(false)
          onError?.(err.message)
        },
      },
    )
  }

  return (
    <Dialog onClose={onClose} title="Choose trigger event" width="large">
      <div className={styles.body}>
        <FormControl>
          <FormControl.Label>Trigger type</FormControl.Label>
          <Select
            value={String(selectedIndex)}
            onChange={e => setSelectedIndex(Number(e.target.value))}
            disabled={triggerDefinitions.length === 0}
          >
            {options.map((option, index) => (
              <Select.Option key={option} value={String(index)}>
                {titleMap[option] ?? option}
              </Select.Option>
            ))}
          </Select>
          {selectedEvent === 'manual' && (
            <FormControl.Caption>The automation will run immediately using its configured prompt.</FormControl.Caption>
          )}
          {selectedEvent === 'interval' && (
            <FormControl.Caption>
              The automation will run as if triggered by its configured schedule.
            </FormControl.Caption>
          )}
        </FormControl>
        {!NO_EVENT_URL_TRIGGERS.has(selectedEvent) && (
          <FormControl>
            <FormControl.Label>Event URL</FormControl.Label>
            <FormControl.Caption>The automation will run as if triggered by this event.</FormControl.Caption>
            <TextInput
              value={resourceUrl}
              onChange={e => setResourceUrl(e.target.value)}
              placeholder={placeholders[selectedEvent] ?? `https://github.com/${nwo}/issues/1`}
              block
            />
          </FormControl>
        )}
      </div>
      {error && (
        <div className={styles.bannerContainer}>
          <Banner variant="critical" title="Run failed" onDismiss={resetError}>
            {error.message}
          </Banner>
        </div>
      )}
      <Dialog.Footer className={styles.footer}>
        <Button onClick={onClose}>Cancel</Button>
        <Button
          variant="primary"
          onClick={handleRun}
          disabled={isRunning || (!NO_EVENT_URL_TRIGGERS.has(selectedEvent) && !resourceUrl.trim())}
        >
          {isRunning ? 'Running...' : 'Run now'}
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}
