import {mainQuery} from '@github-ui/react-core/future/main-query'
import {repoAgentsAppBuilder} from '../config/app-builder'
import type {
  AutomationDetailPayload,
  AutomationsPayload,
  EditAutomationPayload,
  NewAutomationPayload,
} from '../types/automations-payload'

/**
 * Automations list page route configuration.
 */
export const automationsRoute = repoAgentsAppBuilder.createQueryRouteConfig('automationsRoute', {
  path: '/:owner/:repo/agents/automations',
  queries: [mainQuery<AutomationsPayload>()],
})

/**
 * New automation page route configuration.
 */
export const newAutomationRoute = repoAgentsAppBuilder.createQueryRouteConfig('newAutomationRoute', {
  path: '/:owner/:repo/agents/automations/new',
  queries: [mainQuery<NewAutomationPayload>()],
})

/**
 * Individual automation detail page route configuration.
 */
export const automationDetailRoute = repoAgentsAppBuilder.createQueryRouteConfig('automationDetailRoute', {
  path: '/:owner/:repo/agents/automations/:automationID',
  queries: [mainQuery<AutomationDetailPayload>()],
})

/**
 * Edit automation page route configuration.
 */
export const editAutomationRoute = repoAgentsAppBuilder.createQueryRouteConfig('editAutomationRoute', {
  path: '/:owner/:repo/agents/automations/:automationID/edit',
  queries: [mainQuery<EditAutomationPayload>()],
})
