import type {ToolGroup} from './tool-definitions'

/** Builds the system prompt for the "Suggest tools" call: rules, examples, then the catalog. */
export function buildSuggestToolsSystemPrompt(catalog: ToolGroup[]): string {
  const lines: string[] = []
  lines.push(
    'You are helping a user configure an automation agent on GitHub.',
    "Given the agent's name, description, and prompt, choose the minimum",
    'set of tools the agent will need to accomplish its task.',
    '',
    'Approach:',
    "1. Read the user's prompt as a list of concrete actions the agent will take",
    '   (read, list, create, modify, etc.).',
    '2. For each action, pick the tool from the catalog that performs it most',
    '   directly. Skip tools that are merely "related"; include only tools you',
    '   would actually call to complete the task.',
    '3. Consider both gathering inputs (read/list/search) and producing outputs',
    "   (create/update/edit) when they're both implied by the prompt.",
    '',
    'Examples (illustrative; your selection depends on the actual prompt):',
    '',
    'Prompt: "Once a day, summarize new issues from the last 24 hours into a single tracking issue."',
    'Reasoning: list/read recent issues, create one new issue with the summary. No edits to existing issues.',
    'toolIds: ["github/list_issues", "github/issue_read", "github/create_issue"]',
    '',
    'Prompt: "Triage incoming issues by adding labels and assigning a milestone."',
    'Reasoning: list/read issues to know what to triage, then change labels and milestone metadata only.',
    'toolIds: ["github/list_issues", "github/issue_read", "github/update_issue_labels", "github/update_issue_milestone"]',
    '',
    'Prompt: "Daily report on the open PRs as a new tracking issue."',
    'Reasoning: list/read PRs to understand them, then create a new issue with the report. The PRs are not modified.',
    'toolIds: ["github/list_pull_requests", "github/pull_request_read", "github/create_issue"]',
    '',
    'Rules:',
    '- Return ONLY tool IDs that appear in the catalog below.',
    '- Prefer fewer tools. Do not add tools "just in case".',
    "- If the user's intent is unclear or no tools are needed, return an empty array.",
    '- Do not invent new tool IDs.',
    '',
    'Tool catalog:',
  )
  for (const group of catalog) {
    lines.push(`- ${group.name}:`)
    for (const tool of group.tools) {
      lines.push(`  - ${tool.id}: ${tool.name} — ${tool.description}`)
    }
  }
  return lines.join('\n')
}

export interface SuggestionContext {
  name: string
  description: string
  prompt: string
}

export function buildSuggestToolsUserPrompt(context: SuggestionContext): string {
  return [
    `Name: ${context.name.trim() || '(not provided)'}`,
    `Description: ${context.description.trim() || '(not provided)'}`,
    `Prompt: ${context.prompt.trim()}`,
  ].join('\n')
}

/**
 * JSON schema constraining `toolIds` to an enum of known IDs. Callers must
 * still post-filter (empty catalog, duplicates, schema drift).
 */
export function buildSuggestToolsResponseSchema(knownToolIds: string[]) {
  return {
    type: 'json_schema',
    json_schema: {
      name: 'automation_tool_suggestions',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['toolIds'],
        properties: {
          toolIds: {
            type: 'array',
            items: knownToolIds.length > 0 ? {type: 'string', enum: [...knownToolIds]} : {type: 'string'},
          },
        },
      },
    },
  } as const
}

export interface ParseSuggestionResult {
  /** IDs from the model that exist in the known catalog, deduped. */
  validIds: string[]
  /** Count of IDs the model returned that were not in the catalog. */
  filteredOutCount: number
}

/**
 * Parses the model response (string-JSON or object), filters to known IDs,
 * dedupes. Throws on malformed input.
 */
export function parseSuggestToolsResponse(rawContent: unknown, knownToolIds: Iterable<string>): ParseSuggestionResult {
  let parsed: unknown = rawContent
  if (typeof rawContent === 'string') {
    try {
      parsed = JSON.parse(rawContent)
    } catch {
      throw new Error('Could not parse model response as JSON')
    }
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Model response was not an object')
  }

  const maybeIds = (parsed as {toolIds?: unknown}).toolIds
  if (!Array.isArray(maybeIds)) {
    throw new Error('Model response missing toolIds array')
  }

  const knownSet = new Set(knownToolIds)
  const validIds: string[] = []
  const seen = new Set<string>()
  let filteredOutCount = 0
  for (const item of maybeIds) {
    if (typeof item !== 'string') {
      filteredOutCount++
      continue
    }
    if (!knownSet.has(item)) {
      filteredOutCount++
      continue
    }
    if (seen.has(item)) continue
    seen.add(item)
    validIds.push(item)
  }

  return {validIds, filteredOutCount}
}
